<script setup lang="ts">
import { Head } from '@inertiajs/vue3'
import { computed,onMounted,onUnmounted,ref } from 'vue'
import StatCard from '../Components/ui/StatCard.vue'
const props=defineProps<{latest:any;activity:Record<string,number>;queuedBroadcasts:number;history:any[];thresholds:Record<string,number>}>()
const latest=ref(props.latest),activity=ref(props.activity),queuedBroadcasts=ref(props.queuedBroadcasts),history=ref([...props.history])
let stream:EventSource|undefined
onMounted(()=>{stream=new EventSource('/metrics/stream');stream.addEventListener('metrics',(event)=>{try{const data=JSON.parse((event as MessageEvent).data);if(data){latest.value=data;history.value=[...history.value,data].slice(-120)}}catch{}})})
onUnmounted(()=>stream?.close())
const pct=(used:number,total:number)=>total?Math.min(100,Math.max(0,used/total*100)):0
const ram=()=>pct(Number(latest.value?.ram_used_bytes||0),Number(latest.value?.ram_total_bytes||0))
const disk=()=>pct(Number(latest.value?.disk_used_bytes||0),Number(latest.value?.disk_total_bytes||0))
const fmtBytes=(n:number)=>{if(!Number.isFinite(n)||n<0)return '—';if(n===0)return '0 B';const u=['B','KB','MB','GB','TB'];const i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return (n/Math.pow(1024,i)).toFixed(i?1:0)+' '+u[i]}
const warnings=computed(()=>{if(!latest.value)return [];const limits={cpu:Number(props.thresholds.cpu_percent||85),ram:Number(props.thresholds.ram_percent||85),disk:Number(props.thresholds.disk_percent||90)};return [{name:'CPU',value:Number(latest.value.cpu_percent||0),limit:limits.cpu},{name:'RAM',value:ram(),limit:limits.ram},{name:'Disk',value:disk(),limit:limits.disk}].filter(x=>x.value>=x.limit)})
const trend=()=>history.value.map((x,i)=>{const max=Math.max(1,...history.value.map(y=>Number(y.cpu_percent||0)));return (i*100/(history.value.length-1||1))+','+(100-Number(x.cpu_percent||0)*100/max)}).join(' ')
const prometheus=()=>{const raw=latest.value?.prometheus;if(!raw)return [];if(typeof raw==='string'){try{return Object.entries(JSON.parse(raw)).slice(0,12)}catch{return []}}return Object.entries(raw).filter(([k])=>k!=='error').slice(0,12)}
</script>
<template><Head title="داشبورد Matrix Synapse"/><v-container fluid class="pa-6 dashboard-live"><div class="d-flex align-center justify-space-between flex-wrap ga-3 mb-5"><div><h1 class="text-h4">نمای کلی سامانه</h1><div class="text-medium-emphasis">آخرین نمونه: {{ latest?.sampled_at||'در انتظار اولین نمونه‌برداری' }}</div></div><v-chip color="success" variant="tonal" prepend-icon="mdi-access-point">زنده · هر ۱۵ ثانیه</v-chip></div>
<v-skeleton-loader v-if="!latest" type="heading, image, card" class="mb-4"/>
<template v-else>
<v-alert v-for="warning in warnings" :key="warning.name" type="warning" variant="tonal" class="mb-3">هشدار {{ warning.name }}: {{ warning.value.toFixed(1) }}% (آستانه {{ warning.limit }}%)</v-alert>
<v-row><v-col cols="6" md="3"><StatCard title="کل کاربران" :value="latest.users_total??'—'" icon="mdi-account-group" to="/users"/></v-col><v-col cols="6" md="3"><StatCard title="اتاق‌ها" :value="latest.rooms_total??'—'" icon="mdi-forum" to="/rooms"/></v-col><v-col cols="6" md="3"><StatCard title="آنلاین در ۵ دقیقه اخیر" :value="latest.online_users??'—'" icon="mdi-account-clock"/></v-col><v-col cols="6" md="3"><StatCard title="پیام‌های در صف" :value="queuedBroadcasts" icon="mdi-bullhorn" to="/broadcasts"/></v-col></v-row>
<v-row class="mt-1"><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center resource-card"><div class="text-subtitle-1 mb-3">CPU</div><v-progress-circular :model-value="latest.cpu_percent||0" :size="118" :width="11" color="primary">{{ Number(latest.cpu_percent||0).toFixed(1) }}%</v-progress-circular></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center resource-card"><div class="text-subtitle-1 mb-3">RAM</div><v-progress-circular :model-value="ram()" :size="118" :width="11" color="primary">{{ ram().toFixed(1) }}%</v-progress-circular><div class="text-caption text-medium-emphasis mt-2">{{ fmtBytes(latest.ram_used_bytes) }} / {{ fmtBytes(latest.ram_total_bytes) }}</div></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center resource-card"><div class="text-subtitle-1 mb-3">Disk</div><v-progress-circular :model-value="disk()" :size="118" :width="11" color="primary">{{ disk().toFixed(1) }}%</v-progress-circular><div class="text-caption text-medium-emphasis mt-2">{{ fmtBytes(latest.disk_used_bytes) }} / {{ fmtBytes(latest.disk_total_bytes) }}</div></v-card></v-col></v-row>
<v-row><v-col cols="12" md="8"><v-card rounded="xl" class="pa-5"><v-card-title>روند زنده CPU</v-card-title><svg viewBox="0 0 100 100" preserveAspectRatio="none" width="100%" height="155"><polyline :points="trend()" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg><div class="text-caption text-medium-emphasis">آخرین {{ history.length }} نمونه ذخیره‌شده</div></v-card></v-col><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5 h-100"><v-card-title>دسته‌بندی فعالیت</v-card-title><v-list density="compact" bg-color="transparent"><v-list-item v-for="key in ['heavy_active','active','low_active','dormant','suspicious']" :key="key" :title="key" :append-title="String(activity[key]||0)"/></v-list></v-card></v-col></v-row>
<v-row><v-col cols="12" md="4"><StatCard title="اندازه دیتابیس Synapse" :value="fmtBytes(Number(latest.database_bytes||0))" icon="mdi-database"/></v-col><v-col cols="12" md="8"><v-card rounded="xl" class="pa-5 h-100"><v-card-title>متریک‌های Prometheus Synapse</v-card-title><div v-if="prometheus().length" class="d-flex flex-wrap ga-2"><v-chip v-for="[key,value] in prometheus()" :key="key" variant="tonal" size="small">{{ key }}: {{ Number(value).toLocaleString() }}</v-chip></div><div v-else class="text-medium-emphasis text-body-2">متریک Prometheus در دسترس نیست؛ SYNAPSE_PROMETHEUS_URL را بررسی کنید.</div></v-card></v-col></v-row>
</template>
<v-card rounded="xl" class="pa-4 mt-4"><v-card-title>دسترسی سریع</v-card-title><v-card-actions class="flex-wrap"><v-btn color="primary" href="/users">کاربران</v-btn><v-btn href="/rooms">اتاق‌ها</v-btn><v-btn href="/media">مدیا و سهمیه‌ها</v-btn><v-btn href="/activity">فعالیت</v-btn><v-btn href="/metrics">مانیتورینگ</v-btn><v-btn href="/broadcasts">ارسال پیام</v-btn><v-btn href="/server">نسخه Synapse</v-btn><v-btn href="/audit-logs">گزارش رویدادها</v-btn></v-card-actions></v-card></v-container></template>
<style scoped>
.dashboard-live .resource-card{transition:transform .22s ease,box-shadow .22s ease}
.dashboard-live .resource-card:hover{transform:translateY(-3px);box-shadow:0 10px 26px rgba(0,0,0,.10)}
@media(prefers-reduced-motion:reduce){.dashboard-live .resource-card{transition:none}.dashboard-live .resource-card:hover{transform:none}}
</style>
